"""Post-publication test of production update controller against real public mirrors."""
from pathlib import Path
import subprocess,json
R=Path.cwd();W=R/'work';D=W/'v20-live-update-qa';D.mkdir(exist_ok=True)
for name in ['settings.json','manifest.json','package.zip','package.zip.part']:
 p=D/'updates'/name
 if p.exists():p.unlink()
protocol=D/'UpdateProtocolOld.cs';protocol.write_text((W/'windows-app/UpdateProtocol.cs').read_text(encoding='utf8').replace('Current="0.20.0"','Current="0.19.1"'),encoding='utf8')
harness=D/'Live.cs';harness.write_text(r'''using System;using System.IO;using System.Threading;using System.Diagnostics;using System.Collections.Generic;class Program {internal static string DataDir,BaseDir;}class Live {static Dictionary<string,object> Request(Updates u,string action){return UpdateProtocol.Serializer().Deserialize<Dictionary<string,object>>(u.Request(new Dictionary<string,object>{{"action",action}}));}static void Wait(Updates u,string wanted,int seconds){var t=Stopwatch.StartNew();while(t.Elapsed.TotalSeconds<seconds){var x=Request(u,"state");string phase=UpdateProtocol.Text(x,"phase");if(phase==wanted){Thread.Sleep(250);return;}if(phase=="error")throw new Exception(UpdateProtocol.Text(x,"message"));Thread.Sleep(100);}throw new Exception("Timeout waiting for "+wanted);}static void Main(string[] args){Program.DataDir=args[0];Program.BaseDir=args[0];Updates u=null;bool cancelOnce=false;u=new Updates(raw=>{var x=UpdateProtocol.Serializer().Deserialize<Dictionary<string,object>>(raw);if(cancelOnce&&UpdateProtocol.Text(x,"phase")=="downloading"&&x.ContainsKey("received")&&Convert.ToInt64(x["received"])>10000){cancelOnce=false;Request(u,"cancel");}});u.Request(new Dictionary<string,object>{{"action","settings"},{"automatic",false},{"custom","https://ghfast.top/invalid-folio-route/"},{"preferred",""}});Request(u,"check");Wait(u,"available",70);Console.WriteLine("PASS real signed manifest check via parallel fallback routes");cancelOnce=true;Request(u,"download");Wait(u,"available",90);Console.WriteLine("PASS real controller cancels partial download and permits retry");Request(u,"download");Wait(u,"ready",180);Console.WriteLine("PASS invalid preferred mirror falls back and downloads verified official Windows update ZIP");var restored=new Updates(raw=>{});if(UpdateProtocol.Text(Request(restored,"state"),"phase")!="ready")throw new Exception("Cache not restored");Console.WriteLine("PASS signed downloaded update restored after host restart");Request(restored,"check");Wait(restored,"ready",70);Console.WriteLine("PASS downloaded package still permits checking higher releases");}}''',encoding='utf8')
args=['C:/Windows/Microsoft.NET/Framework64/v4.0.30319/csc.exe','/nologo','/codepage:65001','/out:'+str(D/'Live.exe'),'/reference:System.dll','/reference:System.Core.dll','/reference:System.Windows.Forms.dll','/reference:System.Web.Extensions.dll',str(harness),str(protocol),str(W/'windows-app/UpdateKey.cs'),str(W/'windows-app/Updates.cs')]
r=subprocess.run(args,capture_output=True);assert r.returncode==0,r.stdout.decode('gbk',errors='replace')
r=subprocess.run([str(D/'Live.exe'),str(D)],capture_output=True,text=True,encoding='utf8',errors='replace',timeout=440);print(r.stdout);assert r.returncode==0,r.stderr
checks=[line[5:] for line in r.stdout.splitlines() if line.startswith('PASS ')]
(W/'v20-live-update-report.json').write_text(json.dumps({'success':True,'checks':checks,'errors':[]},indent=2),encoding='utf8')
